mapper.update:
UPDATE tb_emp
SET auth_st = 'APPROVED', upd_dt = NOW()
WHERE hosp_div_id = #{hospitalDomain}
  AND emp_id = #{userId}
  AND role_cd = 'USER'
  AND auth_st = 'INACTIVE'

mapper.delete:
DELETE FROM tb_emp
WHERE hosp_div_id = #{hospitalDomain}
  AND emp_id = #{userId}
  AND role_cd = 'USER'
  AND auth_st = 'INACTIVE'

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM tb_ward
    WHERE hosp_div_id = #{hospitalDomain}
      AND ward_id = #{wardId}
)
